    def __init__(self, capacity):
        self.cap = capacity
        self.stks = []

    def push(self, val):
        for s in self.stks:
            if len(s) < self.cap:
                s.append(val)
                return
        self.stks.append([val])

    def pop(self):
        while self.stks and not self.stks[-1]:
            self.stks.pop()
        if not self.stks:
            return -1
        return self.stks[-1].pop()

    def popAtStack(self, index):
        if index >= len(self.stks) or not self.stks[index]:
            return -1
        return self.stks[index].pop()

