        while (!stks.isEmpty() && stks.get(stks.size() - 1).isEmpty())
            stks.remove(stks.size() - 1);
        if (stks.isEmpty()) return -1;
        return stks.get(stks.size() - 1).pop();
    }

    public int popAtStack(int index) {
        if (index >= stks.size() || stks.get(index).isEmpty()) return -1;
        return stks.get(index).pop();
    }
