import heapq

class DinnerPlates:
    def __init__(self, capacity):
        self.cap = capacity
        self.stks = []
        self.free = []

    def push(self, val):
        while self.free and (self.free[0] >= len(self.stks) or len(self.stks[self.free[0]]) == self.cap):
            heapq.heappop(self.free)
        if self.free:
            i = heapq.heappop(self.free)
            self.stks[i].append(val)
        else:
            self.stks.append([val])

    def pop(self):
        while self.stks and not self.stks[-1]:
            self.stks.pop()
        if not self.stks:
            return -1
        val = self.stks[-1].pop()
        heapq.heappush(self.free, len(self.stks) - 1)
        return val

    def popAtStack(self, index):
        if index >= len(self.stks) or not self.stks[index]:
            return -1
        val = self.stks[index].pop()
        heapq.heappush(self.free, index)
        return val

