import java.util.*;

class DinnerPlates {
    private int cap;
    private List<List<Integer>> stks = new ArrayList<>();
    private PriorityQueue<Integer> free = new PriorityQueue<>();

    public DinnerPlates(int capacity) { cap = capacity; }

    public void push(int val) {
        while (!free.isEmpty()) {
            int i = free.peek();
            if (i >= stks.size() || stks.get(i).size() == cap) free.poll();
            else break;
        }
        if (!free.isEmpty()) {
            int i = free.poll();
            stks.get(i).add(val);
        } else {
            List<Integer> s = new ArrayList<>();
            s.add(val);
            stks.add(s);
        }
    }

    public int pop() {
        while (!stks.isEmpty() && stks.get(stks.size() - 1).isEmpty())
            stks.remove(stks.size() - 1);
        if (stks.isEmpty()) return -1;
        List<Integer> s = stks.get(stks.size() - 1);
        int v = s.remove(s.size() - 1);
        free.offer(stks.size() - 1);
        return v;
    }

    public int popAtStack(int index) {
        if (index >= stks.size() || stks.get(index).isEmpty()) return -1;
        List<Integer> s = stks.get(index);
        int v = s.remove(s.size() - 1);
        free.offer(index);
        return v;
    }
}

